        ArrayNode xyzArray = f.arrayNode()
                .add("x")
                .add("y")
                .add("z");

        // ArrayNode ["a","b","c"]
        ArrayNode abcArray = f.arrayNode()
                .add("a")
                .add("b")
                .add("c");

        return Stream.of(
                arguments("Array node edge case – negative integer index",
                        xyzArray, -1, null),
